package com.joyhsin.hotspot;
import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) ResponseEntity<?> bad(Exception e){return out(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(Exception e){return out(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(Exception.class) ResponseEntity<?> error(Exception e){return out(HttpStatus.INTERNAL_SERVER_ERROR,e.getMessage());} private ResponseEntity<?> out(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s.value(),"error",s.getReasonPhrase(),"message",m==null?s.getReasonPhrase():m));} }
